INSERT INTO `careers` (`id`, `country_code`, `state_code`, `city_code`, `work_type`, `job_title`, `position`, `experience`, `skills`, `description`, `candidate_profile`, `career_status`, `created_at`, `updated_at`) VALUES
(13, 'IN', 'TG', 'HYD', 'Work Form Office', 'Sales Executive', 4, '5', 'Sales & Negotiation Skills,Communication Skills,Customer Relationship Management (CRM),Market Research & Analysis,Time Management & Organization, Problem-Solving Skills,Team Collaboration', 'A Sales Executive is responsible for driving revenue growth by identifying and acquiring new customers, maintaining relationships with existing clients, and promoting the company’s products or services. They play a key role in achieving sales targets, understanding customer needs, and closing deals effectively.', 'Bachelor\'s degree in Business, Marketing, or a related field (preferred but not mandatory).\n\nProven experience in sales or business development (1-5 years, depending on the level).\n\nExperience in B2B or B2C sales, depending on the industry.\n\nSelf-motivated, proactive, and results-driven personality.', 'A', '2025-04-01 13:21:08', NULL),
(16, 'IN', 'TG', 'HYD', 'Work Form Office', 'Marketing Manager', 2, '5', 'Design & Creativity,Lead Generation & CRM,Communication & Networking,Market Analysis', 'A Real Estate Marketing Manager is responsible for developing and executing marketing strategies to promote properties, increase brand awareness, and drive sales. They work closely with sales teams, developers, and digital marketing professionals to generate leads and enhance customer engagement.', '✅ Develop and implement real estate marketing campaigns across online and offline channels.\n✅ Manage digital marketing efforts, including SEO, social media, PPC, and email marketing.\n✅ Coordinate with real estate agents, developers, and external agencies for promotional activities.\n✅ Conduct market research to identify trends, customer needs, and competitor strategies.\n✅ Create engaging content, property listings, brochures, and video ads.\n✅ Organize open houses, property expos, and virtual tours.\n✅ Monitor marketing campaign performance and optimize for better results.\n✅ Maintain and enhance the company\'s website and CRM system for lead generation.\n✅ Collaborate with the sales team to align marketing efforts with business goals.', 'A', '2025-04-02 16:31:28', NULL);
