(1346, 133, 19, '<p><strong>Security &amp; Safety:</strong> 3-tier security system, access-controlled entries (cellar &amp; stilt), CCTV surveillance, and solar fencing.</p>', 'A', NULL, NULL, '2026-06-08 10:19:11', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1347, 133, 18, '<p>24x7 power backup</p>', 'A', NULL, NULL, '2026-06-08 10:19:11', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1348, 133, 21, '<p>centralized gas system,</p>', 'A', NULL, NULL, '2026-06-08 10:19:11', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1349, 133, 24, '<h3><strong>Club Oasis Facilities (50,000 SFT)</strong></h3><p>The clubhouse includes the following amenities:</p><ul><li><strong>Sports &amp; Recreation:</strong> Bowling alley, 10m air rifle shooting gallery, 2 squash courts, 3 badminton courts, tennis court-cum-half basketball court, table tennis, billiards, soccer, and a trampoline park/play zone.</li><li><strong>Games &amp; Entertainment:</strong> Premium mini theatre, arcade games, air hockey, card rooms, board games lounge, and rain dance.</li><li><strong>Wellness &amp; Lifestyle:</strong> Rooftop swimming pool, spa &amp; sauna centre, fitness centre, and unisex salon.</li><li><strong>General Facilities:</strong> Double-height foyer, banquet hall, multi-purpose hall, 5 guest rooms, fully equipped kitchen, library, business centre, crèche, café, bistro, ATM, and 3 commercial spaces.</li></ul>', 'A', NULL, NULL, '2026-06-08 10:19:11', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1350, 133, 4, '<ul><li><strong>Structure:</strong> RCC-framed structure.</li><li><strong>Super Structure:</strong> Red brick work in cement mortar.</li><li><strong>Plastering:</strong> Plastering in two coats with sponge finish.</li></ul>', 'A', NULL, NULL, '2026-06-08 10:19:11', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1351, 133, 5, '<ul><li><strong>Main Door:</strong> Best teak wood frame and shutter, finished with Teak Ply/Teak Veneer, aesthetically designed with melamine polishing, and designer hardware of reputed make.</li><li><strong>Internal Doors:</strong> Teak wood frame and designer shutters.</li><li><strong>Windows:</strong> UPVC Windows of APARNA/WINTECH or equivalent make</li></ul>', 'A', NULL, NULL, '2026-06-08 10:19:11', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1352, 133, 6, '<p><strong>Flooring:</strong> Vitrified tiles ($800\\text{mm} \\times 1600\\text{mm}$) of VARMORA or equivalent make.</p>', 'A', NULL, NULL, '2026-06-08 10:19:11', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1353, 133, 7, '<ul><li><strong>Internal Painting:</strong> Smooth luppam/putty finish with premium acrylic Asian paints.</li><li><strong>External Painting:</strong> Combination of Premium Texture/Cement based painting.</li></ul>', 'A', NULL, NULL, '2026-06-08 10:19:11', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1354, 133, 8, '<ul><li><strong>Kitchen:</strong> Municipal and borewell water connection provision for Aqua guard.</li><li>&nbsp;</li></ul>', 'A', NULL, NULL, '2026-06-08 10:19:11', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1355, 133, 9, '<p><strong>Bathrooms and Toilets:</strong></p><ul><li>CP fittings of GROHE/JAQUAR or equivalent make.</li><li>EWC and flush tank of SOMANY/GEBERIT or equivalent make.</li><li>Hot and cold provisioned wall mixer with shower.</li><li>Tiles up to 6\'6\" height.</li><li>Ceramic non-slippery flooring of standard make.</li></ul>', 'A', NULL, NULL, '2026-06-08 10:19:11', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1356, 133, 10, '<ul><li><strong>Wiring:</strong> Concealed copper wiring of Finolex, Polycab, or equivalent make.</li><li><strong>Switches:</strong> Modular switches/sockets from Anchor, Legrand, Havells, or equivalent make.</li><li><strong>Points:</strong> Includes air conditioner points in all bedrooms, geyser points in all toilets, and plug points for the cooking range, chimney, refrigerator, microwave, and mixer/grinder.</li><li><strong>Automation:</strong> Home automation switches.</li><li><strong>Communication:</strong> Provision for telephone points in the master bedroom and drawing area; provision for internet and cable connection in the master bedroom and drawing area.</li></ul>', 'A', NULL, NULL, '2026-06-08 10:19:11', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1357, 133, 15, '<p>6 passenger capacity lift of KONE or equivalent make with granite/vitrified tile cladding.</p>', 'A', NULL, NULL, '2026-06-08 10:19:11', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1358, 133, 16, '<p>Spacious car parking</p>', 'A', NULL, NULL, '2026-06-08 10:19:11', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1359, 133, 17, '<h3><strong>WTP &amp; STP</strong></h3><ul><li>Water Supply for all floors with Gravity based Distribution.</li><li>Sewerage Treatment plant for adequate capacity.</li><li>The water tanks, sumps, Motors, Ducts of all apartments with installations for common use.</li></ul>', 'A', NULL, NULL, '2026-06-08 10:19:11', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1360, 133, 20, '<p>ire Resistance Electrical wires of Polycab/Finolex/Anchor or equivalent make are used.</p>', 'A', NULL, NULL, '2026-06-08 10:19:11', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1361, 134, 4, '<ul><li><strong>Internal:</strong> Sand-based Cement plaster for RCC and masonry surfaces.</li><li><strong>External:</strong> Sand-based Cement plaster for RCC and masonry surfaces.</li><li><strong>Framed Structure:</strong> RCC framed structure resistant to wind and earthquake.</li><li><strong>Super Structure:</strong> Solid Cement Concrete Blocks for external and internal walls.</li><li><strong>Balconies:</strong> Aluminium frame with glass.</li></ul>', 'A', NULL, NULL, '2026-06-09 08:38:17', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1362, 134, 5, '<ul><li><strong>Main Door:</strong> Engineered wood frames with melamine polish; shutter is a flush shutter with veneer on both sides with melamine polish.</li><li><strong>Internal Doors:</strong> Engineered wood frames; shutter is a flush shutter with veneer on both sides with melamine polish.</li><li><strong>Hardware:</strong> Hardware of reputed make.</li><li><strong>French Doors:</strong> Aluminium sliding door with clear glass and provision for mosquito mesh.</li><li><strong>Windows:</strong> Aluminium sliding window with clear glass and provision for mosquito mesh</li></ul>', 'A', NULL, NULL, '2026-06-09 08:38:17', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1363, 134, 6, '<ul><li><strong>Living/Dining/Family Lounge/All Bedrooms/Kitchen/Home Theatre:</strong> 800 x 1600 mm Vitrified tiles of reputed make.</li><li><strong>Bathrooms:</strong> Antiskid Vitrified tiles of reputed make.</li><li><strong>Parking Area:</strong> Full body Vitrified tiles of reputed make.</li><li><strong>Staircase:</strong> Granite or equivalent make.</li><li><strong>Bathrooms:</strong> Premium Vitrified tiles of reputed make up to lintel level.</li><li><strong>Utility/Wash Area:</strong> Premium Vitrified tiles of reputed make up to lintel level</li></ul>', 'A', NULL, NULL, '2026-06-09 08:38:17', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1364, 134, 7, '<ul><li><strong>External:</strong> Texture and paint with two coats of weather shield.</li><li><strong>Internal:</strong> Two coats of emulsion paint over smooth putty finish.</li></ul>', 'A', NULL, NULL, '2026-06-09 08:38:17', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1365, 134, 8, '<ul><li>Provision for electrical and plumbing points for sink and water purifier.</li><li>Power plug for chimney, refrigerator, oven, mixer/grinder, and cooking range/rice cooker.</li></ul>', 'A', NULL, NULL, '2026-06-09 08:38:17', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1366, 134, 9, '<p>All bathrooms include Polished Chrome (CP) and sanitary ware fixtures of reputed make</p>', 'A', NULL, NULL, '2026-06-09 08:38:18', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1367, 134, 10, '<ul><li>Concealed copper wiring of reputed make.</li><li>Power sockets for AC.</li><li>Power points for cooking range/chimney/exhaust fan, refrigerator, microwave oven, mixer/grinder, and water purifier in the kitchen.</li><li>Power socket for washing machine and dishwasher in utility area.</li><li>Three-phase supply for each unit with individual dual source energy meter.</li><li>Miniature Circuit Breakers (MCB) for each distribution board of reputed make.</li><li>Modular switch boards of reputed make.</li></ul>', 'A', NULL, NULL, '2026-06-09 08:38:18', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1368, 134, 19, '<ul><li>Sophisticated round the clock 24/7 Security System.</li><li>Solar fencing throughout the boundary.</li></ul><h3>&nbsp;</h3>', 'A', NULL, NULL, '2026-06-09 08:38:18', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1369, 134, 17, '<ul><li>Centralized water distribution by hydro-pneumatic system for all villas with individual water meters for each villa.</li><li>Water Treatment Plant.</li><li>Sewage Treatment Plant.</li><li>Rainwater harvesting pits provided for recharging ground water levels.</li></ul>', 'A', NULL, NULL, '2026-06-09 08:38:18', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1370, 134, 18, '<p>DG Back up for the common services and for each villa.</p>', 'A', NULL, NULL, '2026-06-09 08:38:18', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1371, 134, 16, '<p>Spacious car parking</p>', 'A', NULL, NULL, '2026-06-09 08:38:18', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1372, 134, 15, '<p>Kone, Johnson, or equivalent make.</p>', 'A', NULL, NULL, '2026-06-09 08:38:18', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1373, 134, 20, '<p><strong>Fire-Resistant Wiring:</strong> The project utilizes fire-resistance electrical wires from reputable brands like Polycab, Finolex, or Anchor (or equivalent) to ensure safety.</p>', 'A', NULL, NULL, '2026-06-09 08:38:18', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1374, 134, 21, '<p>No common gas pipeline</p>', 'A', NULL, NULL, '2026-06-09 08:38:18', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1375, 134, 24, '<h3><strong>Billing System</strong></h3><ul><li>Prepaid billing system for electricity, water, and maintenance.</li></ul><h3><strong>Water Proofing</strong></h3><ul><li>Waterproofing provided for toilets, open terrace, and balcony.</li></ul>', 'A', NULL, NULL, '2026-06-09 08:38:18', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1376, 134, 25, '<p>External and Internal surfaces utilize sand-based cement plaster.</p>', 'A', NULL, NULL, '2026-06-09 08:38:18', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
