(1553, 146, 4, '<ul><li><strong>Structure:</strong> Framed structure; RCC framed structure with earthquake-resistant design based on IS 466:2000.</li><li><strong>Super Structure:</strong> Red brick, 230 mm thick for external walls and 125 mm thick for internal walls</li></ul>', 'A', NULL, NULL, '2026-06-12 10:47:20', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1554, 146, 5, '<ul><li><strong>Main Door:</strong> Designer Teakwood frame (8ft height) with threshold, featuring a teak veneer designer shutter with melamine mat polish, fitted with good quality hardware.</li><li><strong>Internal Doors:</strong> M.T. Wood frame (8ft height) with designer teak veneer shutter and polish, fitted with ironmongery of a premium brand.</li><li><strong>French Doors:</strong> Aluminium sliding or openable doors of a premium brand with good quality hardware.</li><li><strong>Windows:</strong> Aluminium windows of a premium brand with good quality hardware and mosquito mesh.</li></ul>', 'A', NULL, NULL, '2026-06-12 10:47:20', NULL, NULL, NULL, '169.254.169.126', NULL, NULL);
INSERT INTO `project_listing_specifications_mapping` (`id`, `project_listing_id`, `specifications_id`, `description`, `mapping_status`, `created_by_type`, `created_by`, `created_date`, `updated_by_type`, `updated_by`, `updated_date`, `created_ip`, `updated_ip`, `new_column`) VALUES
(1555, 146, 6, '<ul><li><strong>Living/Dining/Bedrooms:</strong> Appropriate size of GVT finished vitrified tile flooring (reputed make).</li><li><strong>Bathrooms:</strong> Best quality acid-resistant, anti-skid designer tiles (reputed make).</li><li><strong>Balconies/Utility/Stores/Servant Room:</strong> Vitrified/Anti-skid tiles (reputed make).</li></ul><h3>&nbsp;</h3>', 'A', NULL, NULL, '2026-06-12 10:47:20', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1556, 146, 7, '<ul><li><strong>Plastering (Internal):</strong> Smooth gypsum punning over 1 coat of plastering in CM 1:6 for walls and ceiling.</li><li><strong>Plastering (External):</strong> 2 coats of plastering in CM 1:6 for external walls.</li><li><strong>Painting (Internal):</strong> 2 coats of emulsion paint over smooth putty finish.</li><li><strong>Painting (External):</strong> Texture or smooth paint with 2 coats of acrylic exterior emulsion.</li></ul>', 'A', NULL, NULL, '2026-06-12 10:47:20', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1557, 146, 8, '<ul><li>Provision for water purifier, exhaust fan, and chimney.</li><li>No counter top; open for modular kitchen.</li><li>Provision for dishwasher and washing machine in utility areas.</li></ul>', 'A', NULL, NULL, '2026-06-12 10:47:20', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1558, 146, 9, '<ul><li>Wall-mounted EWCs with concealed flush tank/valve (reputed make).</li><li>Single lever diverter with wall mixer cum shower (reputed make).</li><li>Provision for geysers in all bathrooms.</li><li>All CP and sanitary fittings are of a reputed make.</li></ul>', 'A', NULL, NULL, '2026-06-12 10:47:20', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1559, 146, 10, '<ul><li>3-phase supply for each unit with individual meter boards.</li><li>Miniature circuit breakers (MCB) for each distribution board of a premium brand.</li><li>Elegant designer modular electrical switches.</li><li>Power outlets/plugs for TV, audio systems, geysers, chimney, refrigerator, microwave ovens, mixer/grinders, washing machine, and dishwasher.</li></ul>', 'A', NULL, NULL, '2026-06-12 10:47:20', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1560, 146, 19, '<p><strong>Security:</strong> Round-the-clock security/surveillance system; building management system; solar-powered fencing all-round the compound; intercom facility from security and villa to villa.</p>', 'A', NULL, NULL, '2026-06-12 10:47:20', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1561, 146, 18, '<p><strong>Generator:</strong> 100% D.G. set backup including A/Cs, with acoustic enclosure.</p>', 'A', NULL, NULL, '2026-06-12 10:47:20', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1562, 146, 15, '<p><strong>Lift:</strong> Provided at an additional cost.</p>', 'A', NULL, NULL, '2026-06-12 10:47:20', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1563, 146, 16, '<p><strong>Car Parking:</strong> Covered MS structure car parking provided as per approved design at an additional cost.</p>', 'A', NULL, NULL, '2026-06-12 10:47:20', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1564, 146, 17, '<p><strong>WTP &amp; STP:</strong> Water treatment plant for borewell water; centralized water distribution by hydro-pneumatic system (with individual water meters); sewage treatment plant of adequate capacity.</p>', 'A', NULL, NULL, '2026-06-12 10:47:20', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1565, 146, 20, '<p><strong>Fire-Resistant Wiring:</strong> The project utilizes fire-resistance electrical wires from reputable brands like Polycab, Finolex, or Anchor (or equivalent) to ensure safety.</p>', 'A', NULL, NULL, '2026-06-12 10:47:20', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1566, 146, 21, '<p>No common gas pipeline</p>', 'A', NULL, NULL, '2026-06-12 10:47:20', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1567, 146, 24, '<p><strong>False Ceiling:</strong> Gypsum board ceiling with electrical wiring by the developer at an additional cost.</p>', 'A', NULL, NULL, '2026-06-12 10:47:20', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1568, 146, 25, '<ul><li><strong>VRV System:</strong> Air conditioning system by the developer at an additional cost.</li><li>&nbsp;</li></ul>', 'A', NULL, NULL, '2026-06-12 10:47:20', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1569, 147, 4, '<ul><li><strong>Frame:</strong> RCC Shear Wall framed structure to withstand Wind &amp; Seismic Loads (ZONE-II).</li><li><strong>Walls:</strong> All internal &amp; external walls are RCC shear walls &amp; Solid Cement Brick masonry walls for Non-Structural walls.</li><li><strong>Floor to Floor Heights:</strong><ul><li><strong>Luxury (Tower 5):</strong> 3.30 m.</li><li><strong>Ultra Premium (Towers 2 &amp; 7):</strong> 3.15 m.</li><li><strong>Premium (Towers 1, 3, 4 &amp; 6):</strong> 3.00 m.</li></ul></li></ul>', 'A', NULL, NULL, '2026-06-13 07:02:59', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1570, 147, 5, '<ul><li><strong>Main Door:</strong> Manufactured teak veneered door frame &amp; shutter with melamine polish. Heights vary by tower type: 7\' (Premium), 7\'6\" (Ultra Premium), and 8\' (Luxury).</li><li><strong>Internal Doors:</strong> Hard wood door frame &amp; laminate shutter with premium hardware. Heights vary by tower type: 7\' (Premium), 7\'6\" (Ultra Premium), and 8\' (Luxury).</li><li><strong>French Doors:</strong> Anodized aluminum frame with double glass (DGU)/toughened glass and mosquito mesh.</li><li><strong>Windows:</strong> UPVC profile sections with clear toughened glass and mosquito mesh for sliding windows.</li><li><strong>Grills/Railings:</strong> Mild steel (MS) window grills; Balconies feature SS railing with glass.</li></ul>', 'A', NULL, NULL, '2026-06-13 07:02:59', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1571, 147, 6, '<ul><li><strong>Drawing, Living, Dining, Pooja:</strong><ul><li><strong>Premium/Ultra Premium:</strong> 800x800mm (Premium) or 800x1200mm (Ultra Premium) double charged vitrified tiles.</li><li><strong>Luxury:</strong> Italian marble flooring.</li></ul></li><li><strong>Bedrooms &amp; Kitchen:</strong><ul><li><strong>Premium/Ultra Premium:</strong> 800x800mm (Premium) or 800x1200mm (Ultra Premium) double charged vitrified tiles.</li><li><strong>Luxury:</strong> Wooden flooring.</li></ul></li><li><strong>Balconies/Bathrooms:</strong> Anti-skid vitrified tiles for balconies; anti-skid ceramic floor tiles and wall dado for bathrooms.</li><li><strong>Others:</strong> Granite/Vitrified tiles for corridors; V.D.F flooring for parking areas.</li></ul>', 'A', NULL, NULL, '2026-06-13 07:02:59', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1572, 147, 7, '<ul><li><strong>External:</strong> Textured finish with two coats of exterior emulsion paint.</li><li><strong>Internal:</strong> Smooth putty finish with 2 coats of premium acrylic emulsion paint.</li></ul>', 'A', NULL, NULL, '2026-06-13 07:02:59', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1573, 147, 8, '<ul><li><strong>Counter/Dado:</strong> Granite platform with stainless steel sink; glazed vitrified tiles up to 2\' height above platform (provided at extra cost).</li><li><strong>Provisions:</strong> Treated borewell/municipal water (softened); space for water purifier, exhaust fan, or chimney.</li></ul>', 'A', NULL, NULL, '2026-06-13 07:02:59', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1574, 147, 15, '<p><strong>Elevators/Lifts:</strong> 6 high-speed automatic passenger lifts and 2 high-speed passenger-cum-service lifts.</p>', 'A', NULL, NULL, '2026-06-13 07:02:59', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1575, 147, 10, '<p><strong>Electrical/Communication:</strong> Telephone points in bedrooms, living, and drawing rooms; intercom facility; cable TV/internet cabling provided.</p>', 'A', NULL, NULL, '2026-06-13 07:02:59', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1576, 147, 21, '<p><strong>Systems:</strong> Centralized gas bank; 50KW solar power for common areas; centralized pest control system (piping in walls); provision for home automation; copper piping for AC unit</p>', 'A', NULL, NULL, '2026-06-13 07:02:59', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1577, 147, 19, '<p><strong>Security/Safety:</strong> 100% DG power backup; video door phone at main entrance; biometric lock for main door; fire hydrant/sprinkler systems per NBC norms.</p>', 'A', NULL, NULL, '2026-06-13 07:02:59', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1578, 147, 20, '<p><strong>Security/Safety:</strong> 100% DG power backup; video door phone at main entrance; biometric lock for main door; fire hydrant/sprinkler systems per NBC norms.</p>', 'A', NULL, NULL, '2026-06-13 07:02:59', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1579, 147, 9, '<p><strong>Bathrooms:</strong> Anti-skid vitrified tiles for balconies; anti-skid ceramic floor tiles and wall dado for bathrooms.</p>', 'A', NULL, NULL, '2026-06-13 07:02:59', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1580, 147, 16, '<p>Spacious car parking</p>', 'A', NULL, NULL, '2026-06-13 07:02:59', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1581, 147, 17, '<p><strong>WTP &amp; STP:</strong> Water treatment plant for borewell water; centralized water distribution by hydro-pneumatic system (with individual water meters); sewage treatment plant of adequate capacity</p>', 'A', NULL, NULL, '2026-06-13 07:02:59', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1582, 147, 18, '<p>100% D.G. set backup</p>', 'A', NULL, NULL, '2026-06-13 07:02:59', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1583, 147, 24, '<p><strong>Internet/TV:</strong> Provision for internet source by a single service provider; telephone in drawing room and master bedroom; DTH and TV services in all bedrooms, living room, and multipurpose hall.</p>', 'A', NULL, NULL, '2026-06-13 07:02:59', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1584, 147, 25, '<p><strong>VRV System:</strong> Air conditioning system by the developer at an additional cost.</p>', 'A', NULL, NULL, '2026-06-13 07:02:59', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1585, 148, 4, '<ul><li><strong>Structure:</strong> RCC framed structure designed to withstand wind and seismic loads.</li><li><strong>Super Structure:</strong> 9\" thick red brick work for external walls and 4.5\" thick red brick work for internal walls.</li><li><strong>Plastering:</strong> One coat of plastering with a sponge finish for walls and ceiling with cement mortar; two coats of plastering for external walls with cement mortar.</li></ul><h3>&nbsp;</h3>', 'A', NULL, NULL, '2026-06-13 10:25:36', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1586, 148, 5, '<p><strong>Doors &amp; Windows:</strong></p><ul><li><strong>Main Door:</strong> M.T. Wood/Manufactured Hard Wood door frame and veneered flush door shutter finished with melamine polish and hardware of reputed make.</li><li><strong>Internal Doors:</strong> M.T. Wood/Manufactured Hard Wood door frame and veneered flush door shutter finished with melamine polish and hardware of reputed make.</li><li><strong>Bathrooms &amp; Utility Doors:</strong> M.T. Wood/Manufactured Hard Wood door frame and flush door shutters with one side melamine polish and one side enamel paint.</li><li><strong>French Doors:</strong> uPVC door frame with plain glass paneled shutters.</li><li><strong>Windows:</strong> uPVC window frame with plain glass shutter and provision for mosquito net/mesh.</li></ul>', 'A', NULL, NULL, '2026-06-13 10:25:36', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1587, 148, 6, '<ul><li><strong>Living, Dining, Bedrooms &amp; Kitchen:</strong> 800x800 mm size double charged vitrified tiles of reputed make.</li><li><strong>Bathrooms:</strong> Anti-skid ceramic tiles of reputed make.</li><li><strong>Corridors:</strong> Marble/Granite flooring.</li><li><strong>Balconies &amp; Utility:</strong> Rustic ceramic tiles of reputed make.</li><li><strong>Staircase:</strong> Granite stone.</li><li><strong>Parking &amp; Driveways:</strong> VDF flooring as per design</li></ul>', 'A', NULL, NULL, '2026-06-13 10:25:36', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1588, 148, 7, '<ul><li><strong>External:</strong> Combination of texture and cement-based putty with primer and two coats of emulsion paint.</li><li><strong>Internal:</strong> Two coats of cement-based putty with primer and two coats of plastic emulsion paint.</li></ul>', 'A', NULL, NULL, '2026-06-13 10:25:36', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1589, 148, 8, '<p><strong>Kitchen:</strong> Provision for water purifier, HOB, chimney, and municipal (HMWSSB) and underground water connections; granite platform topping with 2ft tile dado, sink, and taps.</p>', 'A', NULL, NULL, '2026-06-13 10:25:36', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1590, 148, 9, '<p><strong>Bathrooms:</strong> Medium size washbasin, hot and cold diverter mixer with overhead shower, provision for geysers, concealed flush tank with wall-mounted WC, and chrome-plated fittings (all of reputed make).</p>', 'A', NULL, NULL, '2026-06-13 10:25:36', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1591, 148, 10, '<p><strong>Electrical:</strong> Concealed copper wiring with modular switches (reputed make), 3-phase supply with individual pre-paid meters, MCBs for distribution boards, and power outlets for ACs, geysers, exhaust fans, kitchen appliances, and TV/audio systems.</p>', 'A', NULL, NULL, '2026-06-13 10:25:36', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1592, 148, 15, '<p><strong>Lifts:</strong> High-speed automatic passenger lifts of reputed make with rescue device, V3F for energy efficiency, and granite/marble cladding at entrances.</p>', 'A', NULL, NULL, '2026-06-13 10:25:36', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1593, 148, 17, '<p><strong>WTP &amp; STP:</strong> Underground water with exclusive water softening plant, non-RO plant, water meters for each unit, and sewage treatment plant with treated water used for landscaping and rain water harvesting.</p>', 'A', NULL, NULL, '2026-06-13 10:25:36', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1594, 148, 18, '<p><strong>Generator:</strong> DG set with acoustic enclosure and AMF panel for power backup for fans, lights, common areas, and lifts.</p>', 'A', NULL, NULL, '2026-06-13 10:25:36', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
