(1597, 148, 20, '<p><strong>Safety:</strong> Fire hydrant, sprinkler system, fire alarm, and public addressing system as per National Building Code (NBC) norms</p>', 'A', NULL, NULL, '2026-06-13 10:25:36', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1598, 148, 24, '<p><strong>Accessibility:</strong> Access ramps at all entrances for differently abled individuals.</p>', 'A', NULL, NULL, '2026-06-13 10:25:36', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
