(1601, 149, 4, '<ul><li><strong>Structure:</strong> RCC framed structure as per IS 456(2000).</li><li><strong>Masonry:</strong> External walls are 9\" red brick masonry; internal walls are 4.5\" red brick masonry.</li><li><strong>Plastering:</strong> Internal and external smooth finish plastering with Recron 3S Polypropylene Fibre to prevent air cracks.</li></ul>', 'A', NULL, NULL, '2026-06-15 07:14:57', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1602, 149, 6, '<ul><li><strong>Living, Dining, Bedrooms, Kitchen:</strong> Double charged vitrified tiles.</li><li><strong>Balconies, Utility, Toilets:</strong> Anti-skid ceramic tiles.</li><li><strong>Toilet Wall Tiles:</strong> Glazed finished tiles up to lintel height.</li><li><strong>Parking:</strong> IPS, heavy-duty tiles, or Tandur stone.</li><li><strong>Staircase:</strong> Granite, marble, or vitrified tiles.</li><li><strong>Note:</strong> Only premier brands are used (e.g., Johnson, Kajaria, CERA, Somany, or equivalent).</li></ul>', 'A', NULL, NULL, '2026-06-15 07:14:57', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1603, 149, 5, '<ul><li><strong>Main Door:</strong> Hardwood frame with both sides polished teak finish shutter.</li><li><strong>Bedroom Doors:</strong> Hardwood frame with membrane doors.</li><li><strong>Bathroom Doors:</strong> Waterproof WPC doors.</li><li><strong>Windows:</strong> 3-track UPVC sliding windows with mosquito mesh shutter.</li></ul>', 'A', NULL, NULL, '2026-06-15 07:14:57', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
