(1694, 154, 21, '<p><strong>Centralized Gas</strong>: Piped gas supplied from a centralized bank with pre-paid meters.</p>', 'A', NULL, NULL, '2026-06-16 10:42:03', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1695, 154, 24, '<p><strong>Internet/Cable/Telecom</strong>: Provision for internet and cable TV in the hall and master bedroom; video door phones provided for security.</p>', 'A', NULL, NULL, '2026-06-16 10:42:03', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1696, 154, 25, '<ul><li><strong>Air Conditioning</strong>: Copper piping provided for all halls and bedrooms; ODUs located in concealed, easily serviceable spots.</li><li>&nbsp;</li></ul>', 'A', NULL, NULL, '2026-06-16 10:42:03', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
