(1918, 171, 24, '<p>UGENDAR STRUCTUREUGENDAR STRUCTURETelecommunication: Telephone points in the drawing/living room and all bedrooms; intercom facility connected to security.Cable TV &amp;amp;amp;amp; Internet: Provision for cable in the living room and master bedroom; internet and Wi-Fi provision in the living area.&amp;amp;nbsp;&amp;nbsp;</p>', 'A', NULL, NULL, '2026-07-01 06:48:33', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1919, 171, 25, '<p>UGENDAR STRUCTUREUGENDAR STRUCTURETelecommunication: Telephone points in the drawing/living room and all bedrooms; intercom facility connected to security.Cable TV &amp;amp;amp;amp; Internet: Provision for cable in the living room and master bedroom; internet and Wi-Fi provision in the living area.&amp;amp;nbsp;&amp;nbsp;</p>', 'A', NULL, NULL, '2026-07-01 06:48:33', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1920, 171, 17, '<p>UGENDAR STRUCTUREUGENDAR STRUCTURETelecommunication: Telephone points in the drawing/living room and all bedrooms; intercom facility connected to security.Cable TV &amp;amp;amp;amp; Internet: Provision for cable in the living room and master bedroom; internet and Wi-Fi provision in the living area.&amp;amp;nbsp;&amp;nbsp;</p>', 'A', NULL, NULL, '2026-07-01 06:48:33', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1921, 171, 19, '<p>SecurityFire &amp;amp;amp; SafetyFire &amp;amp;amp;amp; Safety: Sprinkler and hydrant systems on all floors and basements, with fire alarms and a public address system controlled at the main security&amp;amp;nbsp;&amp;nbsp;</p>', 'A', NULL, NULL, '2026-07-01 06:48:33', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1922, 172, 4, '<ul><li><strong>Structure:</strong> RCC framed structure designed to withstand wind and seismic loads.</li><li><strong>Super Structure:</strong> AAC blocks or fly ash bricks are used for external and internal walls.</li></ul>', 'A', NULL, NULL, '2026-07-02 09:07:15', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1923, 172, 5, '<ul><li>&nbsp;<ul><li><strong>Main Door:</strong> Frames are hardwood/engineered with melamine polish; shutters are flush with veneer on both sides with melamine polish.</li><li><strong>Internal Doors:</strong> Frames are hardwood/engineered wood; shutters are flush with veneer on the front side with melamine polish and painted on the rear side.</li><li><strong>Hardware:</strong> Reputed make.</li><li><strong>French Doors:</strong> Premium UPVC sliding door with clear glass.</li><li><strong>Windows:</strong> Premium UPVC sliding windows with clear glass and provision for mosquito mesh.</li></ul></li><li>&nbsp;</li></ul>', 'A', NULL, NULL, '2026-07-02 09:07:15', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1924, 172, 6, '<ul><li><strong>Drawing, living, dining, family &amp; 1st floor lounge:</strong> Large format vitrified tiles of reputed make.</li><li><strong>Staircase:</strong> Leather finish granite (steel grey or equivalent).</li><li><strong>Master bedroom/Cinema room:</strong> Wood finish vitrified tiles of reputed make.</li><li><strong>Other bedrooms &amp; Kitchen:</strong> Large format vitrified tiles of reputed make.</li><li><strong>Bathrooms:</strong> Anti-skid vitrified tiles of reputed make.</li><li><strong>Deck:</strong> Wooden finish vitrified flooring of reputed make</li></ul>', 'A', NULL, NULL, '2026-07-02 09:07:15', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1925, 172, 7, '<ul><li>&nbsp;<ul><li><strong>External:</strong> Texture/smooth paint with two coats of acrylic exterior emulsion; cladding as per façade detail.</li><li><strong>Internal:</strong> 2 coats of emulsion paint over smooth putty finish.</li><li><strong>Staircase railing:</strong> SS railing with glass.</li></ul></li><li>&nbsp;</li></ul>', 'A', NULL, NULL, '2026-07-02 09:07:15', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1926, 172, 8, '<p><strong>Dado:</strong> Polished glazed vitrified tiles of reputed make up to 2 feet in height above the kitchen platform.</p>', 'A', NULL, NULL, '2026-07-02 09:07:15', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1927, 172, 9, '<ul><li><strong>Plumbing &amp; Sanitary:</strong> Polished chrome (CP) and sanitaryware fixtures of reputed make.</li><li><strong>Basin:</strong> Vanity type wash basin with hot and cold mixer.</li><li><strong>WC:</strong> European water closet.</li><li><strong>Shower:</strong> Single level diverter with spout and overhead shower.</li><li><strong>Partition:</strong> Glass partition for master bathroom only.</li><li><strong>Dado:</strong> Vitrified tiles of reputed make up to lintel level.</li></ul>', 'A', NULL, NULL, '2026-07-02 09:07:15', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1928, 172, 10, '<ul><li><strong>Wiring:</strong> Concealed copper wiring of reputed make.</li><li><strong>Sockets:</strong> Power sockets for VRV A.C. systems, kitchen appliances (cooking range, chimney, refrigerator, etc.), and washing machine/dishwasher provision in the utility area.</li><li><strong>Supply:</strong> Three-phase supply with individual source energy meters.</li><li><strong>Components:</strong> Modular switch boards and MCBs of reputed make.</li></ul>', 'A', NULL, NULL, '2026-07-02 09:07:15', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1929, 172, 15, '<p>Provision for a lift</p>', 'A', NULL, NULL, '2026-07-02 09:07:15', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1930, 172, 17, '<ul><li><strong>WTP:</strong> Water Treatment Plant provided for borewell water supply.</li><li><strong>STP:</strong> Sewage Treatment Plant with treated water used for landscaping and flushing.</li><li><strong>System:</strong> Centralized hydro-pneumatic system for water distribution.</li></ul>', 'A', NULL, NULL, '2026-07-02 09:07:15', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(1931, 172, 16, '<p>Spacious Car Parking</p>', 'A', NULL, NULL, '2026-07-02 09:07:15', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
