(2038, 180, 4, '<ul><li>RCC framed structure designed for seismic resistance.</li><li>Earthquake-resistant construction using high-quality concrete.</li><li>AAC block masonry for internal and external walls.</li><li>Premium quality construction materials as per IS standards.</li></ul>', 'A', NULL, NULL, '2026-07-17 06:08:47', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(2039, 180, 5, '<ul><li>Engineered teak wood main door with veneer finish.</li><li>Internal flush doors with laminate finish.</li><li>UPVC sliding windows with mosquito mesh.</li><li>Toughened glass wherever applicable.</li><li>Premium quality hardware fittings.</li></ul>', 'A', NULL, NULL, '2026-07-17 06:08:47', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(2040, 180, 6, '<ul><li>Premium vitrified tiles in living, dining and bedrooms.</li><li>Anti-skid ceramic tiles in bathrooms and balconies.</li><li>Granite flooring for staircase.</li><li>Designer tiles in utility areas.</li></ul>', 'A', NULL, NULL, '2026-07-17 06:08:47', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(2041, 180, 7, '<ul><li>Premium acrylic emulsion paint for interiors.</li><li>Weatherproof exterior emulsion paint.</li><li>Enamel paint for metal grills.</li><li>Smooth wall putty finish.</li></ul>', 'A', NULL, NULL, '2026-07-17 06:08:47', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(2042, 180, 8, '<ul><li>Granite kitchen platform.</li><li>Stainless steel sink with drain board.</li><li>Provision for chimney and water purifier.</li><li>Ceramic tile dado above the kitchen platform.</li></ul>', 'A', NULL, NULL, '2026-07-17 06:08:47', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(2043, 180, 9, '<ul><li>Premium CP fittings.</li><li>Premium sanitary ware.</li><li>Wall-mounted WC with concealed flush tank.</li><li>Anti-skid flooring.</li><li>Provision for geysers in all bathrooms.</li></ul>', 'A', NULL, NULL, '2026-07-17 06:08:47', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(2044, 180, 10, '<ul><li>Concealed copper wiring with modular switches.</li><li>Three-phase power supply.</li><li>MCB and RCCB protection.</li><li>TV, Internet and Telephone points.</li><li>AC provision in all bedrooms.</li></ul>', 'A', NULL, NULL, '2026-07-17 06:08:47', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(2045, 180, 15, '<ul><li>Provision for private lift.</li><li>Lift shaft provided for future installation.</li></ul>', 'A', NULL, NULL, '2026-07-17 06:08:47', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(2046, 180, 16, '<ul><li>Covered parking for 2 cars.</li><li>EV charging point provision.</li><li>Designer paving blocks.</li></ul>', 'A', NULL, NULL, '2026-07-17 06:08:47', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(2047, 180, 17, '<ul><li>Underground water supply system.</li><li>Sewage Treatment Plant (STP).</li><li>Treated water reused for landscaping.</li><li>Rainwater harvesting system.</li></ul>', 'A', NULL, NULL, '2026-07-17 06:08:47', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(2048, 180, 18, '<ul><li>100% DG backup for common areas.</li><li>Power backup for essential points inside villas.</li></ul>', 'A', NULL, NULL, '2026-07-17 06:08:47', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(2049, 180, 19, '<ul><li>24×7 Security.</li><li>CCTV surveillance.</li><li>Solar fencing around the community.</li><li>Video door phone provision.</li><li>Boom barrier at the entrance.</li></ul>', 'A', NULL, NULL, '2026-07-17 06:08:47', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
(2050, 180, 20, '<ul><li>Fire safety system as per statutory norms.</li><li>Fire extinguishers in common areas.</li><li>Emergency evacuation signage.</li></ul>', 'A', NULL, NULL, '2026-07-17 06:08:47', NULL, NULL, NULL, '169.254.169.126', NULL, NULL),
